     @Prop() state: string;
     @Prop() zip: number;
   }

   export type PersonDocument = Person & Document;

   @SchemaFactory.createForClass(Person)
   class PersonSchema extends Person {
     @Prop({ type: [AddressSchema] })
     addresses: Address[];
   }

   export class Person {
     @Prop() name: string;
     @Prop() age: number;
   }
   ```

